const fs=require('fs'); const {chromium}=require('playwright');
const base='https://plan-ex.ru/erpv2', out=process.env.RESULT_DIR||'roles_access_ui_readonly_result';
const cookie=process.env.QA_COOKIE_NAME||'', sid=process.env.QA_LEGACY_SESSION_ID||'';
function must(v,m){if(!v)throw new Error(m)}
(async()=>{fs.mkdirSync(out,{recursive:true});const browser=await chromium.launch({headless:true});try{
 const ctx=await browser.newContext({viewport:{width:1440,height:1000},locale:'ru-RU'});let writes=[];
 await ctx.route('**/*',async route=>{const m=route.request().method().toUpperCase();if(!['GET','HEAD','OPTIONS'].includes(m)){writes.push(m+' '+route.request().url());return route.abort('blockedbyclient')}return route.continue()});
 await ctx.addCookies([{name:cookie,value:sid,url:base,httpOnly:true,secure:true,sameSite:'Lax'}]);const p=await ctx.newPage();
 let r=await p.goto(base+'/company/dashboard',{waitUntil:'domcontentloaded',timeout:60000});must(r&&r.status()===200,'dashboard not 200');must(!p.url().includes('/login'),'upgrade failed');
 const c=(await ctx.cookies(base)).find(x=>x.name===cookie);must(c&&c.value&&c.value!==sid,'SID rotation failed');console.log('ROLES_UI_SESSION_UPGRADE=PASS');
 r=await p.goto(base+'/company/roles-access',{waitUntil:'networkidle',timeout:60000});must(r&&r.status()===200,'roles page not 200');must(await p.locator('[data-roles-access-root]').count()===1,'roles root missing');
 for(const [k,l] of [['roles','Роли'],['users','Пользователи'],['assignments','Закрепления']]){const t=p.locator(`[data-access-tab="${k}"]`);must(await t.count()===1,'tab '+k+' missing');must((await t.innerText()).trim()===l,'tab '+k+' label')}
 must(await p.locator('body').evaluate(el=>el.scrollWidth<=el.clientWidth+1),'horizontal overflow');await p.screenshot({path:`${out}/01_roles_main_1440.png`,fullPage:true});
 await p.locator('[data-access-tab="users"]').click();await p.waitForTimeout(200);must(await p.locator('[data-access-panel="users"]:not(.is-hidden)').count()===1,'users inactive');must(await p.locator('[data-membership-id]').count()>0,'no users');await p.screenshot({path:`${out}/02_users_tab_1440.png`,fullPage:true});
 await p.locator('[data-access-tab="assignments"]').click();await p.waitForFunction(()=>{const n=document.querySelector('[data-assignment-content]');return n&&!/Загрузка закреплений/.test(n.textContent||'')},{timeout:60000});must(await p.locator('[data-assignment-membership]').count()===1,'assignment selector missing');await p.screenshot({path:`${out}/03_assignments_tab_1440.png`,fullPage:true});await p.screenshot({path:`${out}/before_assignments_1440.jpg`,type:'jpeg',quality:58,fullPage:true});
 await p.locator('[data-access-tab="roles"]').click();const rr=p.locator('[data-role-id]').first();must(await rr.count()===1,'no role row');await rr.click();await p.waitForTimeout(150);must(await p.locator('#roles-access-modal[aria-hidden="false"]').count()===1,'role modal missing');must((await p.locator('[data-access-modal-title]').innerText()).trim()==='Настройка роли','role modal title');must(await p.locator('.modal-overlay.is-open').count()===1,'role popup-over-popup');await p.screenshot({path:`${out}/04_role_modal_1440.png`,fullPage:true});await p.locator('[data-access-modal-close]').first().click();must(await p.locator('.modal-overlay.is-open').count()===0,'role modal close');
 await p.locator('[data-access-tab="users"]').click();const ur=p.locator('[data-membership-id]').first();must(await ur.count()===1,'no user row');await ur.click();await p.waitForTimeout(150);must(await p.locator('#roles-access-modal[aria-hidden="false"]').count()===1,'user modal missing');must((await p.locator('[data-access-modal-title]').innerText()).trim()==='Настройка пользователя','user modal title');must(await p.locator('.modal-overlay.is-open').count()===1,'user popup-over-popup');await p.screenshot({path:`${out}/05_user_modal_1440.png`,fullPage:true});await p.screenshot({path:`${out}/before_user_modal_1440.jpg`,type:'jpeg',quality:58,fullPage:true});await p.locator('[data-access-modal-close]').first().click();must(await p.locator('.modal-overlay.is-open').count()===0,'user modal close');must(writes.length===0,'write attempted: '+writes.join(','));
 fs.writeFileSync(`${out}/proof.txt`,['EXACT_PRODUCTION_SHA='+process.env.EXPECTED_SHA,'SESSION_UPGRADE=PASS','ROLES_PAGE_HTTP=200','ROLES_TAB=PASS','USERS_TAB=PASS','ASSIGNMENTS_TAB=PASS','ROLE_MODAL=PASS','USER_MODAL=PASS','POPUP_OVER_POPUP=NO','HORIZONTAL_OVERFLOW=NO','WRITE_REQUESTS=0','BROWSER_UI_PASS=YES'].join('\n')+'\n');console.log('ROLES_ACCESS_READONLY_BROWSER_UI_PASS=YES');console.log('ROLES_ACCESS_POPUP_OVER_POPUP=NO');console.log('ROLES_ACCESS_UI_WRITE_REQUESTS=0');console.log('BEFORE_ASSIGNMENTS_JPEG_BASE64='+fs.readFileSync(`${out}/before_assignments_1440.jpg`).toString('base64'));console.log('BEFORE_USER_MODAL_JPEG_BASE64='+fs.readFileSync(`${out}/before_user_modal_1440.jpg`).toString('base64'));await ctx.close();
}finally{await browser.close()}})().catch(e=>{console.error(e.stack||e);process.exit(1)});
